from decimal import Decimal, ROUND_HALF_UP

def duration_milliseconds(seconds_text):
    value = Decimal(seconds_text)
    if not value.is_finite() or value < 0:
        raise ValueError('duration must be finite and nonnegative')
    return int((value * 1000).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

def validate_clip(payload):
    value = payload['duration_ms']
    if type(value) is not int or value < 0:
        raise ValueError('duration_ms must be a nonnegative integer')
    return payload

